import{_ as s,C as o,o as e,c as h,j as i,a as r,E as n,a2 as t}from"./chunks/framework.C21TwvGF.js";const j=JSON.parse(`{"title":"4-dars (Mentor). Kompyuterning asosiy va qo'shimcha qurilmalari","description":"","frontmatter":{"title":"4-dars (Mentor). Kompyuterning asosiy va qo'shimcha qurilmalari","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"8-sinf (Foundation)","link":"/mentor/8-sinf-cs/"},"week":{"n":2,"link":"/mentor/8-sinf-cs/hafta-02/"},"g":4,"title":"Kompyuterning asosiy va qo'shimcha qurilmalari","lead":"Tizim bloki, monitor va klaviatura kompyuterning faqat «skeleti» xolos. Unga ulangan o'nlab qo'shimcha qurilmalar — printerlar, skanerlar, proyektorlar va drayverlar kompyuterni haqiqiy mo'jizaviy studiyaga aylantiradi. Ushbu darsda kompyuterning barcha a'zolari va ularni xavfsiz ulash sirlarini o'rganamiz.","slide":"/slaydlar/8-sinf-cs/hafta-02/dars-1.html","test":"/slaydlar/8-sinf-cs/hafta-02/dars-1-test.html","student_link":"/8-sinf-cs/hafta-02/dars-1","tabs":[{"g":4,"link":"/mentor/8-sinf-cs/hafta-02/dars-1","current":true},{"g":5,"link":"/mentor/8-sinf-cs/hafta-02/dars-2","current":false},{"g":6,"link":"/mentor/8-sinf-cs/hafta-02/dars-3","current":false}],"prev":null,"next":{"g":5,"title":"Internet, brauzerlar va elektron pochta bilan ishlash","link":"/mentor/8-sinf-cs/hafta-02/dars-2"}}},"headers":[],"relativePath":"mentor/8-sinf-cs/hafta-02/dars-1.md","filePath":"mentor/8-sinf-cs/hafta-02/dars-1.md"}`),d={name:"mentor/8-sinf-cs/hafta-02/dars-1.md"},u={class:"blk"},m={id:"_1-dars-rejasi",tabindex:"-1"},g={class:"blk"},k={id:"_2-dars-konspekti",tabindex:"-1"},y={class:"blk"},p={id:"_3-kod-amaliy-buyruqlar",tabindex:"-1"},q={class:"blk"},v={id:"_4-amaliy-topshiriqlar",tabindex:"-1"},c={class:"blk"},b={id:"_5-tezkor-nazorat",tabindex:"-1"},f={class:"blk"},z={id:"_6-uyga-vazifa",tabindex:"-1"};function _(x,a,D,T,S,A){const l=o("Icon");return e(),h("div",null,[a[18]||(a[18]=i("p",null,[i("strong",null,"Hafta:"),r(" 2 · "),i("strong",null,"Davomiyligi:"),r(" 80 daqiqa · "),i("strong",null,"Turi:"),r(" nazariya + amaliy ko'rgazma · "),i("strong",null,"I-bob"),r(", 4-dars")],-1)),i("div",u,[i("h2",m,[n(l,{name:"file-text"}),a[0]||(a[0]=r(" 1. Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#_1-dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars rejasi"'},"​",-1))]),a[2]||(a[2]=t('<p><strong>Maqsad:</strong> o&#39;quvchilarda kompyuterning asosiy (tizim bloki, monitor, klaviatura, sichqoncha) va qo&#39;shimcha periferiya qurilmalari (printer, skaner, proyektor, veb-kamera, dinamiklar), ularning vazifalari, kiritish/chiqarish portlari (USB, HDMI, DisplayPort, Audio jack) hamda qurilmalarni kompyuterga xavfsiz ulash va drayverlar bilan ishlash bo&#39;yicha to&#39;liq amaliy tushunchalarni shakllantirish.</p><p><strong>Kutiladigan natija:</strong></p><ul><li>Kompyuterning asosiy va qo&#39;shimcha (periferiya) qurilmalarini aniq ajrata oladi.</li><li>Kiritish (input), chiqarish (output) va axborot saqlash (storage) qurilmalari tasnifini biladi.</li><li>Zamonaviy portlar (USB Type-A, USB Type-C, HDMI, DisplayPort, Ethernet RJ-45) va simsiz aloqa (Bluetooth, Wi-Fi) turlarini taniydi.</li><li>Drayver (Driver) tushunchasini va uning periferiya qurilmalarini ishlatishdagi rolini tushuntiradi.</li><li>Qurilmalarni xavfsiz ulash va ajratish («Safely Remove Hardware») qoidalariga rioya qiladi.</li></ul><table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Mazmun</th></tr></thead><tbody><tr><td>0–10 daq</td><td>Takrorlash va kirish</td><td>1-hafta mavzularini takrorlash (arxitektura, Windows, fayllar). «Nega ba&#39;zi printerlar kompyuterga ulanganda darhol ishlamaydi?» muammoli savol</td></tr><tr><td>10–30 daq</td><td>Yangi mavzu: Nazariya</td><td>Asosiy va qo&#39;shimcha qurilmalar, portlar va interfeyslar, drayverlar mohiyati, xavfsiz ulanish</td></tr><tr><td>30–35 daq</td><td>Tanaffus</td><td>Harakatli jismoniy mashqlar</td></tr><tr><td>35–65 daq</td><td>Amaliy mashg&#39;ulot</td><td>Device Manager (Qurilmalar dispetcheri) bilan ishlash, ulangan portlarni tekshirish, drayver holatini ko&#39;rish</td></tr><tr><td>65–75 daq</td><td>Tezkor nazorat</td><td>5 ta savol va interaktiv test</td></tr><tr><td>75–80 daq</td><td>Xulosa va uyga vazifa</td><td>Asosiy xulosalar va uy vazifasini tushuntirish</td></tr></tbody></table><hr>',5))]),i("div",g,[i("h2",k,[n(l,{name:"file-text"}),a[3]||(a[3]=r(" 2. Dars konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#_2-dars-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> 2. Dars konspekti"'},"​",-1))]),a[5]||(a[5]=t('<h3 id="_2-1-kompyuterning-asosiy-qurilmalari" tabindex="-1">2.1. Kompyuterning asosiy qurilmalari <a class="header-anchor" href="#_2-1-kompyuterning-asosiy-qurilmalari" aria-label="Permalink to &quot;2.1. Kompyuterning asosiy qurilmalari&quot;">​</a></h3><p>Kompyuterning to&#39;liq ishlashi va inson u bilan muloqot qilishi uchun zarur bo&#39;lgan minimal to&#39;plam <strong>asosiy qurilmalar</strong> deyiladi. Bular 4 ta:</p><ol><li><strong>Tizim bloki (System Unit):</strong> Barcha hisoblash, ma&#39;lumotlarni qayta ishlash va saqlash jarayonlarini bajaruvchi kompyuterning eng muhim korpusi. Uning ichida ona plata, protsessor (CPU), operativ xotira (RAM), doimiy saqlash disklari (SSD/HDD) va quvvat bloki (PSU) joylashgan.</li><li><strong>Monitor (Displey):</strong> Matn, rasm, video va dasturlar interfeysini vizual tarzda ko&#39;rsatib beruvchi asosiy chiqarish qurilmasi.</li><li><strong>Klaviatura (Keyboard):</strong> Kompyuterga matn, raqamlar va buyruqlarni kiritish uchun xizmat qiluvchi asosiy kiritish qurilmasi.</li><li><strong>Sichqoncha (Mouse):</strong> Grafik interfeysdagi kursor yordamida obyektlarni boshqarish, tanlash va ishga tushirish uchun xizmat qiluvchi kiritish qurilmasi.</li></ol><h3 id="_2-2-qo-shimcha-periferiya-qurilmalar" tabindex="-1">2.2. Qo&#39;shimcha (periferiya) qurilmalar <a class="header-anchor" href="#_2-2-qo-shimcha-periferiya-qurilmalar" aria-label="Permalink to &quot;2.2. Qo&#39;shimcha (periferiya) qurilmalar&quot;">​</a></h3><p>Kompyuterning imkoniyatlarini kengaytiruvchi, tashqi tomondan ulanadigan barcha qurilmalar <strong>qo&#39;shimcha (periferiya) qurilmalar</strong> deyiladi. Ular vazifasiga ko&#39;ra uch guruhga bo&#39;linadi:</p><ol><li><strong>Qo&#39;shimcha kiritish qurilmalari:</strong><ul><li><em>Skaner:</em> Qog&#39;ozdagi hujjat yoki rasmni raqamli tasvirga aylantiradi.</li><li><em>Veb-kamera:</em> Videoqo&#39;ng&#39;iroqlar va jonli efir uchun video tasvirni kompyuterga kiritadi.</li><li><em>Mikrofon:</em> Ovozli signallarni raqamli audio formatga aylantiradi.</li><li><em>Grafik planshet (Stylus bilan):</em> Rassom va dizaynerlar uchun qalam bilan chizish imkonini beradi.</li></ul></li><li><strong>Qo&#39;shimcha chiqarish qurilmalari:</strong><ul><li><em>Printer:</em> Kompyuterdagi elektron hujjat yoki rasmni qog&#39;ozga chop etadi (Lazerli va Purkagichli/Inkjet turlari bor).</li><li><em>Proyektor:</em> Kompyuter ekranidagi tasvirni katta devorga yoki maxsus matoga kattalashtirib aks ettiradi.</li><li><em>Akustik tizim (Kolonkalar va naushniklar):</em> Raqamli tovush signallarini insonga eshitiladigan akustik to&#39;lqinlarga aylantiradi.</li></ul></li><li><strong>Tashqi saqlash qurilmalari:</strong><ul><li><em>USB fleshka (Flash drive):</em> Ixcham, ko&#39;chma flesh-xotira qurilmasi.</li><li><em>Tashqi qattiq disk (External HDD/SSD):</em> Katta hajmdagi ma&#39;lumotlarni nusxalash va zaxira (backup) qilish uchun ishlatiladi.</li></ul></li></ol><h3 id="_2-3-ulanish-portlari-va-interfeyslar" tabindex="-1">2.3. Ulanish portlari va interfeyslar <a class="header-anchor" href="#_2-3-ulanish-portlari-va-interfeyslar" aria-label="Permalink to &quot;2.3. Ulanish portlari va interfeyslar&quot;">​</a></h3><p>Qurilmalar tizim blokiga maxsus tirqishlar — <strong>portlar</strong> orqali ulanadi:</p><ul><li><strong>USB (Universal Serial Bus):</strong> Eng universal port (klaviatura, sichqoncha, fleshka, printer ulanadi). Hozirgi kunda <code>USB Type-A</code> va ikki tomonlama ishlaydigan zamonaviy <code>USB Type-C</code> keng tarqalgan.</li><li><strong>HDMI va DisplayPort:</strong> Monitorni va proyektorni ulash uchun yuqori aniqlikdagi video hamda audio uzatuvchi raqamli portlar.</li><li><strong>Ethernet (RJ-45):</strong> Simli internet va lokal tarmoq kabelini ulash porti.</li><li><strong>Audio Jack (3.5 mm):</strong> Naushnik va mikrofon uchun audio tirqish.</li><li><strong>Simsiz interfeyslar:</strong> Bluetooth (quloqchin, klaviatura, sichqoncha uchun) va Wi-Fi (internet uchun).</li></ul><h3 id="_2-4-drayver-driver-nima" tabindex="-1">2.4. Drayver (Driver) nima? <a class="header-anchor" href="#_2-4-drayver-driver-nima" aria-label="Permalink to &quot;2.4. Drayver (Driver) nima?&quot;">​</a></h3><p><strong>Drayver</strong> — operatsion tizimga yangi ulangan qurilma bilan qanday gaplashishni o&#39;rgatuvchi maxsus mikrodastur. Agar kompyuterga yangi printer yoki videokarta ulasangiz, operatsion tizim uning drayverisiz qurilmaning barcha imkoniyatlaridan foydalana olmaydi. Zamonaviy Windows tizimida ko&#39;plab drayverlar «Plug and Play» (Ula va Ishlat) texnologiyasi orqali avtomatik tarzda o&#39;rnatiladi.</p><h3 id="_2-5-xavfsiz-foydalanish-qoidalari" tabindex="-1">2.5. Xavfsiz foydalanish qoidalari <a class="header-anchor" href="#_2-5-xavfsiz-foydalanish-qoidalari" aria-label="Permalink to &quot;2.5. Xavfsiz foydalanish qoidalari&quot;">​</a></h3><ol><li>Fleshka va tashqi disklarni to&#39;satdan sug&#39;urib olmang! Doimo vazifalar panelidan «Safely Remove Hardware» (Qurilmani xavfsiz ajratish) buyrug&#39;ini bering, aks holda fayllar shikastlanishi mumkin.</li><li>Kompyuter qismlarini tozalashda yoki yangi qurilma ulashda elektr tarmog&#39;idan uzilganligiga ishonch hosil qiling.</li><li>Statik elektr zaryadi nozik chiplarga zarar yetkazmasligi uchun korpusning metall qismiga qo&#39;l tekkizib zaryadsizlaning.</li></ol><hr>',14))]),i("div",y,[i("h2",p,[n(l,{name:"file-text"}),a[6]||(a[6]=r(" 3. Kod / Amaliy buyruqlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#_3-kod-amaliy-buyruqlar","aria-label":'Permalink to "<Icon name="file-text" /> 3. Kod / Amaliy buyruqlar"'},"​",-1))]),a[8]||(a[8]=t(`<p>Windows tizimida ulangan barcha qurilmalar va drayverlar holatini tekshirish:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;"># 1. Qurilmalar dispetcherini (Device Manager) tezkor ochish</span></span>
<span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">Win + X -&gt; Device Manager (yoki devmgmt.msc buyrug</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">&#39;i)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"># 2. Ulangan USB va Bluetooth qurilmalari ro&#39;</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">yxatini ko</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">&#39;rish</span></span>
<span class="line"><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">Win + I -&gt; Bluetooth &amp; devices</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"># 3. Printerlar va skanerlar bo&#39;</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">limini ochish</span></span>
<span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">Win + I -&gt; Bluetooth &amp; devices -&gt; Printers &amp; scanners</span></span></code></pre></div><hr>`,3))]),i("div",q,[i("h2",v,[n(l,{name:"file-text"}),a[9]||(a[9]=r(" 4. Amaliy topshiriqlar ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#_4-amaliy-topshiriqlar","aria-label":'Permalink to "<Icon name="file-text" /> 4. Amaliy topshiriqlar"'},"​",-1))]),a[11]||(a[11]=t('<h3 id="_1-topshiriq-oson" tabindex="-1">1-topshiriq (oson) <a class="header-anchor" href="#_1-topshiriq-oson" aria-label="Permalink to &quot;1-topshiriq (oson)&quot;">​</a></h3><p><code>Win + X</code> tugmalarini bosing va menyudan «Device Manager» (Qurilmalar dispetcheri)ni oching (yoki <code>Win + R</code> orqali <code>devmgmt.msc</code> kiriting). Kompyuteringizga ulangan klaviatura, sichqoncha va displey adapteri (videokarta) nomlarini aniqlang.</p><p><strong>Kutiladigan natija:</strong> Kompyuterga ulangan 3 ta asosiy qurilmaning drayver ro&#39;yxatidagi nomi daftarga yoziladi.</p><p><strong>Yechim:</strong></p><ol><li><code>Win + X</code> bosilib, «Device Manager» tanlanadi.</li><li>«Keyboards» bandi ochilib, klaviatura modeli ko&#39;riladi (masalan, <em>Standard PS/2 Keyboard</em> yoki <em>HID Keyboard Device</em>).</li><li>«Mice and other pointing devices» bo&#39;limida sichqoncha ko&#39;riladi.</li><li>«Display adapters» bo&#39;limida videokarta nomi (masalan, <em>Intel UHD Graphics</em> yoki <em>NVIDIA GeForce GTX 1650</em>) aniqlanadi.</li></ol><hr><h3 id="_2-topshiriq-o-rta" tabindex="-1">2-topshiriq (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-o-rta" aria-label="Permalink to &quot;2-topshiriq (o&#39;rta)&quot;">​</a></h3><p>Kompyuteringizning tizim blokida (yoki noutbuk korpusida) mavjud barcha tashqi portlarni ko&#39;zdan kechiring. Quyidagi portlarning nechta donadan borligini aniqlang va jadval tuzing:</p><ol><li>USB Type-A portlari soni.</li><li>USB Type-C porti bormi?</li><li>Monitor ulash uchun qaysi port bor (HDMI, DisplayPort yoki VGA)?</li><li>3.5 mm audio tirqish va Ethernet (tarmoq) porti mavjudligi.</li></ol><p><strong>Kutiladigan natija:</strong> Kompyuterning portlari to&#39;liq sanab chiqilgan jadval.</p><p><strong>Yechim:</strong></p><ol><li>Korpusning old, orqa va yon tomonlari tekshiriladi.</li><li>Masalan: USB 3.0 Type-A — 4 ta, USB Type-C — 1 ta, HDMI — 1 ta, Audio Jack — 1 ta, RJ-45 Ethernet — 1 ta. Natija tartibli jadvalga yoziladi.</li></ol><hr><h3 id="_3-topshiriq-qiyin" tabindex="-1">3-topshiriq (qiyin) <a class="header-anchor" href="#_3-topshiriq-qiyin" aria-label="Permalink to &quot;3-topshiriq (qiyin)&quot;">​</a></h3><p>Fleshkani kompyuterga ulang, unga kichik fayl yozing. So&#39;ngra uni birdaniga sug&#39;urib olish o&#39;rniga, Windows vazifalar panelining o&#39;ng burchagidagi «Safely Remove Hardware and Eject Media» (Xavfsiz ajratish) amali orqali chiqarib oling. Nima uchun bu amal doimiy saqlash qurilmalari uchun muhimligini texnik jihatdan asoslang.</p><p><strong>Kutiladigan natija:</strong> Xavfsiz ajratish amali to&#39;g&#39;ri bajariladi; keshlash va xotira kontrolleri ma&#39;lumotlarni oxirigacha yozib ulgurishi kerakligi tushuntiriladi.</p><p><strong>Yechim:</strong></p><ol><li>Vazifalar panelining o&#39;ng quyi burchagidagi kichik strelka (System Tray) bosiladi.</li><li>Fleshka belgisi ustiga bosilib, «Eject [Fleshka nomi]» tanlanadi.</li><li>«Safe to Remove Hardware» xabari chiqqandan keyingina qurilma sug&#39;uriladi.</li><li>Asoslash: Operatsion tizim fayllarni birdaniga diskka yozmasdan, vaqtincha kesh xotirada (RAM buffer) ushlab turishi mumkin. To&#39;satdan sug&#39;urilganda keshdagi ma&#39;lumot yozilmay qolib, fayl tizimi (<code>FAT32</code>/<code>NTFS</code>) buziladi va fleshka «format talab qiladigan» bo&#39;lib qoladi.</li></ol><hr>',19))]),i("div",c,[i("h2",b,[n(l,{name:"file-text"}),a[12]||(a[12]=r(" 5. Tezkor nazorat ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#_5-tezkor-nazorat","aria-label":'Permalink to "<Icon name="file-text" /> 5. Tezkor nazorat"'},"​",-1))]),a[14]||(a[14]=t("<ol><li>Kompyuterning 4 ta asosiy qurilmasini ayting. <ul><li><em>Javob:</em> Tizim bloki, monitor, klaviatura, sichqoncha.</li></ul></li><li>Qo&#39;shimcha (periferiya) qurilma deb nimaga aytiladi? <ul><li><em>Javob:</em> Kompyuter imkoniyatlarini kengaytirish uchun tashqi tomondan ulanadigan barcha qo&#39;shimcha asboblar (printer, skaner, veb-kamera, proyektor).</li></ul></li><li>Skaner va Printerning asosiy farqi nimada? <ul><li><em>Javob:</em> Skaner — kiritish qurilmasi (qog&#39;ozdan kompyuterga o&#39;tkazadi); Printer — chiqarish qurilmasi (kompyuterdan qog&#39;ozga chop etadi).</li></ul></li><li>Drayver (Driver) nima uchun kerak? <ul><li><em>Javob:</em> Operatsion tizim yangi ulangan apparat qurilmasi bilan to&#39;g&#39;ri muloqot qilishi va uni boshqarishi uchun zarur bo&#39;lgan dastur.</li></ul></li><li>Zamonaviy monitorlar tizim blokiga qaysi portlar orqali ulanadi? <ul><li><em>Javob:</em> HDMI va DisplayPort (eski kompyuterlarda VGA/DVI).</li></ul></li></ol><hr>",2))]),i("div",f,[i("h2",z,[n(l,{name:"file-text"}),a[15]||(a[15]=r(" 6. Uyga vazifa ",-1)),a[16]||(a[16]=i("a",{class:"header-anchor",href:"#_6-uyga-vazifa","aria-label":'Permalink to "<Icon name="file-text" /> 6. Uyga vazifa"'},"​",-1))]),a[17]||(a[17]=i("ol",null,[i("li",null,"Uyingizdagi yoki maktabdagi kompyuterga qanday periferiya qurilmalari (printer, naushnik, veb-kamera va h.k.) ulanganligini daftaringizga ro'yxat qilib yozing va ularni «Kiritish» hamda «Chiqarish» turlariga ajrating."),i("li",null,[r("Kompyuteringizda "),i("code",null,"Win + X"),r(" → «Device Manager» orqali «Audio inputs and outputs» bo'limini ochib, o'rnatilgan dinamik va mikrofon nomini yozib oling. Vazifani bajarish vaqti: 20 daqiqa.")])],-1))])])}const I=s(d,[["render",_]]);export{j as __pageData,I as default};
